#pragma once
/**
 * =========================================================================================
 * @file core/gpu/gpu_ink_manager.hpp
 * @brief SDL_GPU Hardware-Accelerated Triangle Mesh Inking Manager
 * =========================================================================================
 *
 * ARCHITECTURAL ROLE & DESIGN:
 * ----------------------------
 * `GpuInkManager` provides hardware-accelerated GPU rasterization for variable-width
 * vector ink meshes (`Folio::InkMesh` / `Folio::InkVertex` generated by `InkMeshBuilder`)
 * using SDL3's modern `SDL_GPU` API (Vulkan / Direct3D 12 / Metal).
 *
 * All canvas rendering flows through `LayerCompositorManager`:
 * - Layer 1 (`BakedCanvasLayer`): Submits committed `InkContainer` stroke meshes into
 *   batched GPU draw calls and composites them onto the Layer 1 backing surface.
 * - Layer 2 (`LiveInteractionLayer`): Submits active in-flight and Kalman-predicted
 *   stroke meshes (`InkEngine::GetLiveMesh()`, `InkEngine::GetPredictedMesh()`) directly
 *   to the GPU pipeline within the localized dirty scissor rectangle.
 */

#include <SDL3/SDL.h>
#include <SDL3/SDL_gpu.h>
#include <blend2d/blend2d.h>
#include <cstdint>
#include <vector>
#include <string>

#include "core/ink_engine/ink_engine.hpp"
#include "input/pen_palette.hpp"

namespace Folio {

/**
 * @struct GpuStrokeUniforms
 * @brief Vertex uniform buffer layout (std140 aligned, 48 bytes) pushed per draw call.
 */
struct GpuStrokeUniforms {
    float transform0[4] = {1.0f, 0.0f, 0.0f, 1.0f};        ///< m00, m01, m10, m11
    float transform1[4] = {0.0f, 0.0f, 1920.0f, 1080.0f};  ///< m20, m21, viewportW, viewportH
    float params[4]     = {1.0f, 1.0f, 0.5f, 0.0f};        ///< scalePxPerMm, opacity, baseDepth, pad
};

/**
 * @class GpuInkManager
 * @brief Manages SDL_GPUDevice, graphics pipelines, vertex/index streaming buffers, and layer compositing.
 */
class GpuInkManager {
public:
    /**
     * @brief Global singleton accessor used by the layer system (`LayerCompositorManager`).
     */
    static GpuInkManager& Instance();

    GpuInkManager() = default;
    ~GpuInkManager();

    GpuInkManager(const GpuInkManager&) = delete;
    GpuInkManager& operator=(const GpuInkManager&) = delete;

    /**
     * @brief Initializes the SDL_GPUDevice and compiles SPIR-V stroke graphics pipelines.
     * Safe to call multiple times; returns true if the GPU pipeline is ready.
     */
    bool Init();

    /**
     * @brief Releases all SDL_GPU resources, pipelines, textures, and buffers.
     */
    void Shutdown();

    /**
     * @brief Queries whether the SDL_GPU device (or direct OpenGL ES fallback) and stroke pipelines are initialized and active.
     */
    [[nodiscard]] bool IsAvailable() const noexcept { return m_initialized && (m_device != nullptr || m_glesInitialized); }

    /**
     * @brief Enables or disables GPU/GLES stroke rendering (falls back to CPU when disabled).
     */
    void SetEnabled(bool enabled) noexcept { m_enabled = enabled; }
    [[nodiscard]] bool IsEnabled() const noexcept { return m_enabled && IsAvailable(); }

    /**
     * @brief Returns the active GPU backend driver name (e.g. "vulkan", "direct3d12", "metal", "opengles").
     */
    [[nodiscard]] const char* GetDriverName() const noexcept;

    /**
     * @brief Resets transient per-pass vertex, index, and draw-command staging arrays.
     */
    void BeginBatch() noexcept;

    /**
     * @brief Appends an indexed triangle stroke mesh (`InkMesh`) to the current GPU batch.
     *
     * @param mesh          Indexed triangle mesh generated by `InkMeshBuilder::BuildSolidMesh`.
     * @param worldToScreen Combined 2D affine matrix mapping mesh coordinates to screen pixels.
     * @param scalePxPerMm  Effective pixel-per-mm scale factor for screen-space edge anti-aliasing.
     * @param opacity       Combined stroke/container opacity multiplier [0.0, 1.0].
     * @param blendMode     Compositing mode (`Normal`, `Multiply`, `Additive`).
     */
    void SubmitMesh(const InkMesh& mesh,
                    const BLMatrix2D& worldToScreen,
                    float scalePxPerMm,
                    float opacity = 1.0f,
                    BlendMode blendMode = BlendMode::Normal,
                    uint32_t strokeId = 0,
                    bool isPencil = false);

    /**
     * @brief Queries whether any stroke meshes are queued in the current batch.
     */
    [[nodiscard]] bool HasPendingDraws() const noexcept { return !m_drawCommands.empty(); }

    /**
     * @brief Executes all queued GPU mesh draws onto a Blend2D `BLImage` surface within `[clipX, clipY, clipW, clipH]`.
     *
     * @param targetSurface Target `BL_FORMAT_PRGB32` image surface.
     * @param clipX         Scissor X origin in pixels.
     * @param clipY         Scissor Y origin in pixels.
     * @param clipW         Scissor width in pixels (<= 0 means full surface width).
     * @param clipH         Scissor height in pixels (<= 0 means full surface height).
     * @return true if the GPU pass executed and composited onto `targetSurface`.
     */
    bool FlushToSurface(BLImage& targetSurface,
                        int clipX = 0,
                        int clipY = 0,
                        int clipW = -1,
                        int clipH = -1);

    /**
     * @brief Flushes the active `BLContext` and executes queued GPU mesh draws onto its backing `BLImage`.
     */
    bool FlushToContext(BLContext& ctx,
                        int clipX = 0,
                        int clipY = 0,
                        int clipW = -1,
                        int clipH = -1);

    // Telemetry queries
    [[nodiscard]] uint32_t GetLastVertexCount() const noexcept { return m_lastVertexCount; }
    [[nodiscard]] uint32_t GetLastTriangleCount() const noexcept { return m_lastTriangleCount; }
    [[nodiscard]] uint32_t GetLastDrawCallCount() const noexcept { return m_lastDrawCallCount; }

    // Memory footprint queries (bytes)
    [[nodiscard]] size_t GetVertexCapacityBytes() const noexcept { return m_vertexCapacity; }
    [[nodiscard]] size_t GetIndexCapacityBytes() const noexcept { return m_indexCapacity; }
    [[nodiscard]] size_t GetImageTransferCapacityBytes() const noexcept { return m_imageTransferCapacity; }
    [[nodiscard]] size_t GetTextureMemoryBytes() const noexcept {
        return static_cast<size_t>(m_textureWidth) * static_cast<size_t>(m_textureHeight) * 4u;
    }
    [[nodiscard]] size_t GetDepthStencilMemoryBytes() const noexcept {
        return m_depthStencilTexture ? (static_cast<size_t>(m_textureWidth) * static_cast<size_t>(m_textureHeight) * 4u) : 0;
    }

    void SetLayerPassActive(bool active) noexcept { m_layerPassActive = active; }
    [[nodiscard]] bool IsLayerPassActive() const noexcept { return m_layerPassActive; }

    void SetActiveClipRect(int x, int y, int w, int h) noexcept {
        m_activeClipX = x;
        m_activeClipY = y;
        m_activeClipW = w;
        m_activeClipH = h;
    }

    void ClearActiveClipRect() noexcept {
        m_activeClipX = 0;
        m_activeClipY = 0;
        m_activeClipW = -1;
        m_activeClipH = -1;
    }

private:
    enum class PipelineType : uint8_t {
        NormalOpaque = 0,
        NormalCore,
        NormalSkirt,
        MultiplyCore,
        MultiplySkirt,
        Additive,
        PencilCore,
        PencilSkirt
    };

    struct DrawCommand {
        uint32_t indexOffset  = 0;
        uint32_t indexCount   = 0;
        int32_t  vertexOffset = 0;
        PipelineType pipeline = PipelineType::NormalOpaque;
        uint32_t strokeId     = 0;
        GpuStrokeUniforms uniforms;
    };

    bool CreatePipelines();
    bool EnsureCanvasTexture(uint32_t width, uint32_t height);
    bool EnsureGeometryBuffers(uint32_t vertexBytes, uint32_t indexBytes);
    bool EnsureImageTransferBuffers(uint32_t byteSize);

    // Direct OpenGL ES fallback pipeline
    bool InitGlesFallback();
    void ShutdownGlesFallback();
    bool FlushToSurfaceGLES(BLImageData& imgData, int surfW, int surfH, int rx, int ry, int rw, int rh);

    SDL_GPUDevice*           m_device                = nullptr;
    SDL_GPUShader*           m_vertexShader          = nullptr;
    SDL_GPUShader*           m_fragmentShader        = nullptr;
    SDL_GPUShader*           m_fragmentShaderPencil  = nullptr;
    SDL_GPUGraphicsPipeline* m_pipelineNormal        = nullptr;
    SDL_GPUGraphicsPipeline* m_pipelineNormalCore    = nullptr;
    SDL_GPUGraphicsPipeline* m_pipelineNormalSkirt   = nullptr;
    SDL_GPUGraphicsPipeline* m_pipelineMultiplyCore  = nullptr;
    SDL_GPUGraphicsPipeline* m_pipelineMultiplySkirt = nullptr;
    SDL_GPUGraphicsPipeline* m_pipelineAdditive      = nullptr;
    SDL_GPUGraphicsPipeline* m_pipelinePencilCore    = nullptr;
    SDL_GPUGraphicsPipeline* m_pipelinePencilSkirt   = nullptr;

    SDL_GPUTextureFormat     m_depthStencilFormat  = SDL_GPU_TEXTUREFORMAT_INVALID;
    SDL_GPUTexture*          m_depthStencilTexture = nullptr;

    SDL_GPUTexture*          m_canvasTexture    = nullptr;
    uint32_t                 m_textureWidth     = 0;
    uint32_t                 m_textureHeight    = 0;

    SDL_GPUBuffer*           m_vertexBuffer     = nullptr;
    SDL_GPUTransferBuffer*   m_vertexTransfer   = nullptr;
    uint32_t                 m_vertexCapacity   = 0;

    SDL_GPUBuffer*           m_indexBuffer      = nullptr;
    SDL_GPUTransferBuffer*   m_indexTransfer    = nullptr;
    uint32_t                 m_indexCapacity    = 0;

    SDL_GPUTransferBuffer*   m_imageUploadTransfer   = nullptr;
    SDL_GPUTransferBuffer*   m_imageDownloadTransfer = nullptr;
    uint32_t                 m_imageTransferCapacity = 0;

    std::vector<InkVertex>   m_stagedVertices;
    std::vector<uint32_t>    m_stagedIndices;
    std::vector<DrawCommand> m_drawCommands;

    // Direct OpenGL ES fallback state
    bool     m_glesInitialized          = false;
    uint32_t m_glesProgram              = 0;
    uint32_t m_glesProgramPencil        = 0;
    uint32_t m_glesVao                  = 0;
    uint32_t m_glesVbo                  = 0;
    uint32_t m_glesIbo                  = 0;
    int32_t  m_glesLocTransform0        = -1;
    int32_t  m_glesLocTransform1        = -1;
    int32_t  m_glesLocParams            = -1;
    int32_t  m_glesLocPencilTransform0  = -1;
    int32_t  m_glesLocPencilTransform1  = -1;
    int32_t  m_glesLocPencilParams      = -1;
    uint32_t m_glesFbo                  = 0;
    uint32_t m_glesCanvasTex     = 0;
    uint32_t m_glesRboDepthStencil = 0;
    uint32_t m_glesTexWidth      = 0;
    uint32_t m_glesTexHeight     = 0;

    uint32_t m_nextAutoStrokeId  = 1;
    bool     m_initialized       = false;
    bool     m_initAttempted     = false;
    bool     m_enabled           = true;
    bool     m_layerPassActive   = false;
    int      m_activeClipX       = 0;
    int      m_activeClipY       = 0;
    int      m_activeClipW       = -1;
    int      m_activeClipH       = -1;
    uint32_t m_lastVertexCount   = 0;
    uint32_t m_lastTriangleCount = 0;
    uint32_t m_lastDrawCallCount = 0;
};

} // namespace Folio
